// Before minification
function fahrenheitToCelsius(fahrenheit) {
    // convert the temperature
    var celsius = (fahrenheit - 32) * 5 / 9;
    return celsius;
}

// After minification
function fahrenheitToCelsius(e){return 5*(e-32)/9}
